"""Pydantic v2 schemas for the AI patient summary API."""

from datetime import datetime
from typing import List, Optional

from pydantic import BaseModel, ConfigDict, Field

# Default disclaimer used when the LLM does not return its own.
DEFAULT_DISCLAIMER = (
    "This summary was generated by AI from the patient's monitoring records and "
    "may contain inaccuracies. It is for informational review by the assigned "
    "doctor and must not be used as the sole basis for clinical decisions."
)

DEFAULT_DATA_LIMITATIONS = [
    "Pulse and symptom fields are not captured by the BloodPressureReading model in this system.",
    "Structured BP targets, medication lists, and treatment status are not stored as structured fields in the available data model.",
]


class AISummarySection(BaseModel):
    title: str
    content: str
    supporting_data: List[str] = Field(default_factory=list)


class AISummaryRaw(BaseModel):
    """Intermediate schema used to validate the LLM's raw JSON output."""
    patient_id: Optional[int] = None
    generated_at: Optional[datetime] = None
    period_days: Optional[int] = None
    sections: List[AISummarySection] = Field(default_factory=list)
    data_limitations: List[str] = Field(default_factory=list)
    disclaimer: Optional[str] = None
    model_config = ConfigDict(extra="ignore")


class AISummaryResponse(BaseModel):
    """Validated response returned by the AI summary endpoint."""

    patient_id: int
    generated_at: datetime
    period_days: int
    sections: List[AISummarySection] = Field(default_factory=list)
    data_limitations: List[str] = Field(default_factory=list)
    disclaimer: str = DEFAULT_DISCLAIMER

    model_config = ConfigDict(from_attributes=True)
